using System;using System.Data;using System.Drawing;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;using RetailSales.BUS;using RetailSales.DAL;using RetailSales.DTO;
namespace RetailSales { public class MainForm:Form { RetailBUS bus=new RetailBUS();TabControl tabs=new TabControl();DataGridView master=new DataGridView(),products=new DataGridView(),cartGrid=new DataGridView(),top=new DataGridView();ComboBox table=new ComboBox(),staff=new ComboBox(),customer=new ComboBox();TextBox search=new TextBox(),code=new TextBox(),qty=new TextBox();Label total=new Label();List<CartItem> cart=new List<CartItem>();public MainForm(){Text="BÀI 6.1 - QUẢN LÝ BÁN HÀNG SIÊU THỊ MINI";Width=1180;Height=760;StartPosition=FormStartPosition.CenterScreen;tabs.Dock=DockStyle.Fill;Controls.Add(tabs);BuildManage();BuildSale();BuildReport();} void SetupGrid(DataGridView g){g.Dock=DockStyle.Fill;g.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;g.SelectionMode=DataGridViewSelectionMode.FullRowSelect;g.MultiSelect=false;g.AllowUserToAddRows=false;g.ReadOnly=true;} void BuildManage(){var p=new TabPage("Danh mục");tabs.TabPages.Add(p);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};table.DropDownStyle=ComboBoxStyle.DropDownList;table.Items.AddRange(new object[]{"SanPham","KhachHang","NhanVien"});table.SelectedIndex=0;table.Width=150;table.SelectedIndexChanged+=(s,e)=>LoadMaster();search.Width=220;var bSearch=new Button{Text="Tìm sản phẩm"};bSearch.Click+=(s,e)=>{master.DataSource=bus.Search(search.Text);};var add=new Button{Text="Thêm"};add.Click+=(s,e)=>EditRow(true);var edit=new Button{Text="Sửa"};edit.Click+=(s,e)=>EditRow(false);var del=new Button{Text="Xóa"};del.Click+=(s,e)=>DeleteRow();var reload=new Button{Text="Tải lại"};reload.Click+=(s,e)=>LoadMaster();bar.Controls.AddRange(new Control[]{new Label{Text="Bảng:",AutoSize=true,Padding=new Padding(0,8,0,0)},table,search,bSearch,add,edit,del,reload});SetupGrid(master);p.Controls.Add(master);p.Controls.Add(bar);LoadMaster();} void LoadMaster(){try{master.DataSource=bus.Get(table.Text);}catch(Exception ex){Err(ex);}} void EditRow(bool add){try{string t=table.Text;DataTable dt=bus.Get(t);DataRow r=dt.NewRow();if(!add){if(master.CurrentRow==null)return;foreach(DataColumn c in dt.Columns)r[c.ColumnName]=master.CurrentRow.Cells[c.ColumnName].Value??DBNull.Value;}using(var f=new RowEditor(dt,r,add,t)){if(f.ShowDialog()==DialogResult.OK){if(add)bus.Insert(t,r);else bus.Update(t,r);LoadMaster();}}}catch(Exception ex){Err(ex);}} void DeleteRow(){try{if(master.CurrentRow==null)return;string key=table.Text=="SanPham"?"MaSP":table.Text=="KhachHang"?"MaKH":"MaNV";object id=master.CurrentRow.Cells[key].Value;if(MessageBox.Show("Xóa bản ghi đang chọn?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;bus.Delete(table.Text,id);LoadMaster();}catch(Exception ex){Err(ex);}}
 void BuildSale(){var p=new TabPage("Bán hàng / Hóa đơn");tabs.TabPages.Add(p);var left=new Panel{Dock=DockStyle.Left,Width=510,Padding=new Padding(8)};var right=new Panel{Dock=DockStyle.Fill,Padding=new Padding(8)};p.Controls.Add(right);p.Controls.Add(left);var filter=new FlowLayoutPanel{Dock=DockStyle.Top,Height=42};search=new TextBox{Width=180};var find=new Button{Text="Tìm"};find.Click+=(s,e)=>{products.DataSource=bus.Search(search.Text);};filter.Controls.AddRange(new Control[]{search,find});SetupGrid(products);products.Dock=DockStyle.Fill;var addbar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=42};code=new TextBox{Width=100};qty=new TextBox{Width=55,Text="1"};var add=new Button{Text="Thêm vào giỏ"};add.Click+=(s,e)=>AddCart();addbar.Controls.AddRange(new Control[]{code,qty,add});left.Controls.Add(products);left.Controls.Add(filter);left.Controls.Add(addbar);products.CellDoubleClick+=(s,e)=>{if(products.CurrentRow!=null){code.Text=Convert.ToString(products.CurrentRow.Cells["MaSP"].Value);AddCart();}};
 var selectors=new FlowLayoutPanel{Dock=DockStyle.Top,Height=75};staff.DropDownStyle=ComboBoxStyle.DropDownList;staff.Width=170;customer.DropDownStyle=ComboBoxStyle.DropDownList;customer.Width=190;selectors.Controls.AddRange(new Control[]{new Label{Text="Nhân viên",AutoSize=true},staff,new Label{Text="Khách hàng",AutoSize=true},customer});SetupGrid(cartGrid);cartGrid.DataSource=null;var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=95};total.Text="Tổng tiền: 0 đ";total.AutoSize=true;total.Font=new Font("Segoe UI",14,FontStyle.Bold);var remove=new Button{Text="Bỏ dòng chọn"};remove.Click+=(s,e)=>{if(cartGrid.CurrentRow!=null){cart.RemoveAt(cartGrid.CurrentRow.Index);RefreshCart();}};var pay=new Button{Text="THANH TOÁN",Height=42,Width=150};pay.Click+=(s,e)=>Pay();bottom.Controls.AddRange(new Control[]{total,remove,pay});right.Controls.Add(cartGrid);right.Controls.Add(selectors);right.Controls.Add(bottom);LoadSaleLists();products.DataSource=bus.Search("");} void LoadSaleLists(){try{staff.DataSource=new RetailDAL().Query("SELECT MaNV,TenNV FROM NhanVien");staff.DisplayMember="TenNV";staff.ValueMember="MaNV";customer.Items.Clear();customer.Items.Add("Khách lẻ");var dt=new RetailDAL().Query("SELECT MaKH,TenKH FROM KhachHang");foreach(DataRow r in dt.Rows)customer.Items.Add(new KeyValuePair<int,string>(Convert.ToInt32(r[0]),r[1].ToString()));customer.DisplayMember="Value";customer.ValueMember="Key";customer.SelectedIndex=0;}catch(Exception ex){Err(ex);}} void AddCart(){try{string id=code.Text.Trim();int n=int.Parse(qty.Text);if(n<=0)throw new Exception("Số lượng phải lớn hơn 0");var dt=bus.Search(id);DataRow r=dt.AsEnumerable().FirstOrDefault(x=>x["MaSP"].ToString()==id);if(r==null)throw new Exception("Không tìm thấy mã sản phẩm");var old=cart.FirstOrDefault(x=>x.MaSP==id);if(old==null)cart.Add(new CartItem{MaSP=id,TenSP=r["TenSP"].ToString(),DonGia=Convert.ToDecimal(r["GiaBan"]),SoLuong=n});else old.SoLuong+=n;RefreshCart();}catch(Exception ex){Err(ex);}} void RefreshCart(){cartGrid.DataSource=null;cartGrid.DataSource=cart.Select(x=>new{ x.MaSP,x.TenSP,x.DonGia,x.SoLuong,ThanhTien=x.ThanhTien}).ToList();total.Text="Tổng tiền: "+cart.Sum(x=>x.ThanhTien).ToString("N0")+" đ";} void Pay(){try{if(staff.SelectedValue==null)throw new Exception("Cần có nhân viên bán hàng");int? kh=null;if(customer.SelectedItem is KeyValuePair<int,string>)kh=((KeyValuePair<int,string>)customer.SelectedItem).Key;decimal sum=cart.Sum(x=>x.ThanhTien);bus.Pay(Convert.ToInt32(staff.SelectedValue),kh,cart);MessageBox.Show("Thanh toán thành công! Tổng tiền: "+sum.ToString("N0")+" đ","Thông báo");cart.Clear();RefreshCart();products.DataSource=bus.Search("");}catch(Exception ex){Err(ex);}} void BuildReport(){var p=new TabPage("Báo cáo - Thống kê");tabs.TabPages.Add(p);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55};var day=new Label{AutoSize=true,Padding=new Padding(5),Font=new Font("Segoe UI",12)};var month=new Label{AutoSize=true,Padding=new Padding(5),Font=new Font("Segoe UI",12)};var load=new Button{Text="Cập nhật thống kê"};load.Click+=(s,e)=>{try{day.Text="Doanh thu hôm nay: "+bus.RevenueDay().ToString("N0")+" đ";month.Text="Doanh thu tháng này: "+bus.RevenueMonth().ToString("N0")+" đ";top.DataSource=bus.Top5();}catch(Exception ex){Err(ex);}};bar.Controls.AddRange(new Control[]{day,month,load});SetupGrid(top);p.Controls.Add(top);p.Controls.Add(bar);load.PerformClick();} void Err(Exception e){MessageBox.Show(e.Message,"Lỗi",MessageBoxButtons.OK,MessageBoxIcon.Error);} }
 public class RowEditor:Form { public RowEditor(DataTable dt,DataRow row,bool add,string table){Text=add?"Thêm "+table:"Sửa "+table;Width=460;Height=520;StartPosition=FormStartPosition.CenterParent;var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,AutoScroll=true,Padding=new Padding(12)};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,130));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(panel);foreach(DataColumn c in dt.Columns){if(c.AutoIncrement||(!add&&(c.ColumnName=="MaSP"||c.ColumnName=="MaKH"||c.ColumnName=="MaNV")))continue;var lab=new Label{Text=c.ColumnName,AutoSize=true,Anchor=AnchorStyles.Left};var box=new TextBox{Dock=DockStyle.Top,Text=row[c]==DBNull.Value?"":Convert.ToString(row[c])};panel.Controls.Add(lab);panel.Controls.Add(box);box.Tag=c.ColumnName;}var ok=new Button{Text="Lưu",DialogResult=DialogResult.OK};var cancel=new Button{Text="Hủy",DialogResult=DialogResult.Cancel};panel.Controls.Add(ok);panel.Controls.Add(cancel);AcceptButton=ok;CancelButton=cancel;ok.Click+=(s,e)=>{try{foreach(Control x in panel.Controls)if(x is TextBox){string col=(string)x.Tag;Type t=dt.Columns[col].DataType;if(string.IsNullOrWhiteSpace(x.Text)){row[col]=DBNull.Value;}else if(t==typeof(int))row[col]=int.Parse(x.Text);else if(t==typeof(decimal))row[col]=decimal.Parse(x.Text);else row[col]=x.Text;} }catch(Exception ex){MessageBox.Show("Dữ liệu không hợp lệ: "+ex.Message);DialogResult=DialogResult.None;}};} }
}